    default: "2s",
    description: "Marker label",
  },
  count: {
    type: "number",
    default: 260,
    min: 0,
    max: 780,
    step: 1,
    description: "Count",
    hiddenFromList: false,
  },
  marker: {
    type: "number",
    default: 0.733,
    min: 0,
    max: 2.2,
