    max: 700,
    step: 100,
    description: "Weight",
    hiddenFromList: false,
  },
  pourLength: {
    type: "number",
    default: 50,
    min: 10,
    max: 100,
    step: 1,
    description: "Pour length (frames)",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Geist",
