    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","label","markerLabel","count","marker","fontWeight","pourLength","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "95% of renders under 2s",
  markerLabel: "2s",
  count: 260,
  marker: 0.733,
  fontWeight: 400,
  pourLength: 50,
  accent: "#3B5BFD",
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type GaltonStackElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GaltonStackBase>;

const GaltonStackInner = forwardRef<
  HTMLDivElement,
  GaltonStackElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GaltonStack>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GaltonStackBase
          {...(componentProps as unknown as ComponentProps<typeof GaltonStackBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GaltonStack = Interactive.withSchema({
  Component: GaltonStackInner,
  componentName: "<GaltonStack>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
